	const blocks = m => m.kind === 'dynkey' ? !!m.unwrap || hasAwait(m.key) || (!!m.init && hasAwait(code.slice(m.init.s, m.init.e)))
		: m.kind === 'emit' ? !!m.star || hasAwait(code.slice(m.init.s, m.init.e)) : ['spine', 'acquire'].includes(slotOf(m, code));
